export const revisionModes=[['review','导师意见修改','基于导师意见，逐段完善'],['polish','学术润色','优化表达，核对逻辑与术语'],['rewrite','论文降重','结合真实来源，调整重复表达'],['reduce','降 AI 率','减少套话，保留真实研究内容']];
export const splitParagraphs=text=>String(text).replace(/\r\n?/g,'\n').split(/\n[ \t]*\n/).filter(p=>p.trim());
export const revisedText=doc=>doc.paragraphs.map(p=>p.accepted?p.suggestion:p.original).join('\n\n');
export function createRevision({title,text,mode='review',projectId='',requirements='',fileName='',warnings=[],sourceId=''},id,now){if(!title.trim()||title.length>200)throw Error('请填写不超过 200 字符的文稿标题。');if(!text.trim()||text.length>100000)throw Error('请提供正文，最多 100,000 字符。');const blocks=splitParagraphs(text);if(blocks.some(p=>p.length>20000))throw Error('单段最多 20,000 字符，请用空行分段。');if(blocks.length>500)throw Error('最多 500 段，请分章节创建修改任务。');if(!revisionModes.some(m=>m[0]===mode))throw Error('修改类型无效。');return {id,title:title.trim(),tool:mode==='polish'?'rewrite':mode,revision:true,mode,projectId,requirements:requirements.slice(0,5000),fileName,warnings,sourceId,original:text,text,createdAt:now,updatedAt:now,date:now,stage:'draft',paragraphs:blocks.map((original,i)=>({id:'p'+i,original,suggestion:original,reason:'',comment:'',resolved:false,accepted:false})),versions:[]};}
export function editParagraph(doc,index,patch){if(!doc.paragraphs[index])throw Error('段落不存在。');const safe=Object.fromEntries(Object.entries(patch).filter(([k])=>['suggestion','reason','comment','resolved','accepted'].includes(k)));const paragraph={...doc.paragraphs[index],...safe};if(paragraph.suggestion.length>20000)throw Error('单段修改最多 20,000 字符。');if(patch.suggestion!==undefined&&patch.suggestion!==doc.paragraphs[index].suggestion)paragraph.accepted=false;const paragraphs=doc.paragraphs.map((p,i)=>i===index?paragraph:p);const result={...doc,paragraphs};if(revisedText(result).length>100000)throw Error('修改稿最多 100,000 字符。');return result;}
export function acceptParagraph(doc,index){const p=doc.paragraphs[index];if(!p?.suggestion.trim())throw Error('修改稿为空，请先填写；不会自动删除原文。');return editParagraph(doc,index,{accepted:true});}
export function snapshot(doc,id,now,label='保存修改'){if(doc.versions.length>=50)throw Error('当前已保存 50 个版本，请导出备份；历史版本不会自动删除。');return {...doc,text:revisedText(doc),updatedAt:now,date:now,versions:[...doc.versions,{id,at:now,label,title:doc.title,projectId:doc.projectId,requirements:doc.requirements,paragraphs:doc.paragraphs.map(p=>({...p}))}]};}
export function restoreVersion(doc,id){const v=doc.versions.find(v=>v.id===id);if(!v)throw Error('版本不存在。');return {...doc,title:v.title??doc.title,projectId:v.projectId??doc.projectId,requirements:v.requirements,paragraphs:v.paragraphs.map(p=>({...p})),text:revisedText({paragraphs:v.paragraphs})};}
export function difference(original,next){const a=Array.from(original),b=Array.from(next);let start=0,end=0;while(start<Math.min(a.length,b.length)&&a[start]===b[start])start++;while(end<a.length-start&&end<b.length-start&&a[a.length-1-end]===b[b.length-1-end])end++;return {prefix:a.slice(0,start).join(''),removed:a.slice(start,a.length-end).join(''),added:b.slice(start,b.length-end).join(''),suffix:a.slice(a.length-end).join('')};}
